export async function callTool(name, args = {}) {
  if (name !== 'file_metadata') {
    throw new Error(`Unknown tool: ${name}`);
  }

  const input = args && typeof args === 'object' ? args : {};
  if (typeof input.path !== 'string' || input.path.length === 0) {
    throw new Error('Missing required argument: path');
  }

  const requested = input.path;

  // Normalize and resolve strictly within the data directory.
  const dataDir = DATA_DIR;
  const resolved = path.resolve(dataDir, requested);

  // Reject path traversal outside of the data directory.
  if (
    resolved !== dataDir &&
    !resolved.startsWith(dataDir + path.sep)
  ) {
    throw new Error('Path traversal is not allowed');
  }

  let stats;
  try {
    stats = fs.statSync(resolved);
  } catch {
    throw new Error(`File not found: ${requested}`);
  }

  if (!stats.isFile()) {
    throw new Error(`Not a file: ${requested}`);
  }

  const relativePath = path.relative(dataDir, resolved);
  const ext = path.extname(resolved).toLowerCase();
  const size = stats.size;

  const meta = {
    path: relativePath,
    size,
    extension: ext,
  };

